// ---------------------------------------------------------------------------
// bitboard.hpp - bitboard primitives, attack tables and magic bitboards.
//
// All attack tables are built once at start-up by init_bitboards():
//   * pawn / knight / king attacks: static tables,
//   * rook / bishop / queen attacks: magic bitboards (multipliers generated by
//     tools/gen_magics.cpp, checked into magic_numbers.inc),
//   * BetweenBB / LineBB: square-geometry tables used for pins, check evasions
//     and castling paths.
// ---------------------------------------------------------------------------
#pragma once

#include "utilities/types.hpp"

#if defined(_MSC_VER)
#include <intrin.h>
#endif

#include <string>

namespace stockbear {

// --- Bit utilities -----------------------------------------------------------
inline int popcount(Bitboard b) {
#if defined(_MSC_VER)
    // Portable software popcount; __popcnt64 would require POPCNT at runtime.
    b = b - ((b >> 1) & 0x5555555555555555ULL);
    b = (b & 0x3333333333333333ULL) + ((b >> 2) & 0x3333333333333333ULL);
    return int((((b + (b >> 4)) & 0x0F0F0F0F0F0F0F0FULL) *
                0x0101010101010101ULL) >> 56);
#else
    return __builtin_popcountll(b);
#endif
}

inline Square lsb_square(Bitboard b) {
#if defined(_MSC_VER)
    unsigned long idx;
    _BitScanForward64(&idx, b);
    return Square(idx);
#else
    return Square(__builtin_ctzll(b));
#endif
}

inline Bitboard square_bb(Square s) { return Bitboard(1) << int(s); }

// Pop and return the least significant square. `b` must be non-zero.
inline Square pop_lsb(Bitboard& b) {
    Square s = lsb_square(b);
    b &= b - 1;
    return s;
}

inline bool more_than_one(Bitboard b) { return bool(b & (b - 1)); }

// --- Shifts (no wrap-around: callers must mask file boundaries) --------------
template <int Delta>
inline constexpr Bitboard shift_bb(Bitboard b) {
    if constexpr (Delta >= 0) return b << Delta;
    else                      return b >> (-Delta);
}

// --- Files / ranks ------------------------------------------------------------
inline constexpr Bitboard FileABB = 0x0101010101010101ULL;
inline constexpr Bitboard FileHBB = 0x8080808080808080ULL;
inline constexpr Bitboard Rank1BB = 0x00000000000000FFULL;
inline constexpr Bitboard Rank2BB = 0x000000000000FF00ULL;
inline constexpr Bitboard Rank7BB = 0x00FF000000000000ULL;
inline constexpr Bitboard Rank8BB = 0xFF00000000000000ULL;
inline constexpr Bitboard AllSquaresBB = ~Bitboard(0);

// --- Tables (defined in bitboard.cpp, filled by init_bitboards) ---------------
extern Bitboard FileBB[FileNB];
extern Bitboard RankBB[RankNB];
extern Bitboard AdjacentFilesBB[FileNB];
// Ranks strictly ahead of a square for the given color (whole ranks).
extern Bitboard ForwardRanksBB[ColorNB][RankNB];
extern Bitboard PawnAttacksBB[ColorNB][SQ_NB];
extern Bitboard KnightAttacksBB[SQ_NB];
extern Bitboard KingAttacksBB[SQ_NB];
// Squares strictly between two squares (0 when not aligned or adjacent).
extern Bitboard BetweenBB[SQ_NB][SQ_NB];
// The full line through two aligned squares (0 when not aligned).
extern Bitboard LineBB[SQ_NB][SQ_NB];
// Passed-pawn test masks: squares that must not hold an enemy pawn.
extern Bitboard PassedPawnMaskBB[ColorNB][SQ_NB];
// King zone used by king-safety evaluation (3 files around the king, pushed
// one rank towards the enemy side, plus the king's own squares).
extern Bitboard KingZoneBB[ColorNB][SQ_NB];

// --- Magic bitboards ------------------------------------------------------------
struct Magic {
    Bitboard* attacks;   // attack table for this square
    Bitboard  mask;      // relevant occupancy mask
    Bitboard  magic;     // multiplier
    int       shift;     // 64 - bits(mask)
};

extern Magic RookMagics[SQ_NB];
extern Magic BishopMagics[SQ_NB];

inline Bitboard rook_attacks_bb(Square s, Bitboard occ) {
    const Magic& m = RookMagics[s];
    return m.attacks[((occ & m.mask) * m.magic) >> m.shift];
}

inline Bitboard bishop_attacks_bb(Square s, Bitboard occ) {
    const Magic& m = BishopMagics[s];
    return m.attacks[((occ & m.mask) * m.magic) >> m.shift];
}

inline Bitboard queen_attacks_bb(Square s, Bitboard occ) {
    return rook_attacks_bb(s, occ) | bishop_attacks_bb(s, occ);
}

// Attacks of a sliding piece type (Bishop/Rook/Queen) from `s` given `occ`.
Bitboard slider_attacks_bb(PieceType pt, Square s, Bitboard occ);

// Attacks of any piece type (pawns use the color of the ATTACKER).
Bitboard attacks_bb(PieceType pt, Color attackerColor, Square s, Bitboard occ);

// --- Geometry helpers -------------------------------------------------------
inline bool aligned(Square a, Square b, Square c) {
    return bool(LineBB[a][b] & square_bb(c));
}

// --- Init / debug -----------------------------------------------------------
void init_bitboards();

// Human readable bitboard (for diagnostics; prints to stderr-friendly string).
std::string bitboard_to_string(Bitboard b);

} // namespace stockbear
